function validate([arrays]) {
  if (arrays.length < 2 || arrays.length > 100) return 'arrays needs 2 to 100 arrays.';
  for (const array of arrays) {
    if (array.length < 1 || array.length > 100) return 'Each array has 1 to 100 values.';
    for (let j = 0; j < array.length; j++) {
      if (array[j] < 1 || array[j] > 100) return 'Values are between 1 and 100.';
      if (j > 0 && array[j] <= array[j - 1]) return 'Each array must be strictly increasing.';
    }
  }
  return null;
}

