function longestCommonSubsequence(arrays) {
  const count = new Array(101).fill(0);
  for (const array of arrays) {
    for (const value of array) {
      count[value]++;
    }
  }
  const common = [];
  for (let value = 1; value <= 100; value++) {
    if (count[value] === arrays.length) {
      common.push(value);
    }
  }
  return common;
}

