function longestCommonSubsequence(arrays) {
  // Merge-style intersection with two pointers, one array at a time.
  let common = arrays[0];
  for (let k = 1; k < arrays.length; k++) {
    const next = [];
    let i = 0;
    let j = 0;
    while (i < common.length && j < arrays[k].length) {
      if (common[i] === arrays[k][j]) { next.push(common[i]); i++; j++; }
      else if (common[i] < arrays[k][j]) i++;
      else j++;
    }
    common = next;
  }
  return common;
}

