function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const top = large ? 100 : [5, 12, 100][pick(3)];
  const k = large ? 60 + pick(41) : 2 + pick(4);
  // A shared core makes common values likely; each array then adds its own extras.
  const core = [];
  const coreChance = rand() < 0.2 ? 0 : rand() * (large ? 0.4 : 0.6);
  for (let v = 1; v <= top; v++) if (rand() < coreChance) core.push(v);
  const arrays = [];
  for (let a = 0; a < k; a++) {
    const extra = rand() * (large ? 0.9 : 0.5);
    const values = [];
    for (let v = 1; v <= top; v++) if (core.includes(v) || rand() < extra) values.push(v);
    if (values.length === 0) values.push(1 + pick(top));
    arrays.push(values);
  }
  return [arrays];
}
